sys_script_fix.script:
gs.info('Fix Related list Scope of App service: Fixing the scope of Application service table related list');
var gr = new GlideRecord('sys_ui_related_list');
if (gr.get('af583ea73b000300d20ee79c83efc47a')) {
    if (gr.getValue('sys_scope') == '65c1ca2cdbb2120091285411cf961963') {
        gr.setValue('sys_scope', 'global');

        if (gr.update()) {
            gs.info('Fix Related list Scope of App service: Successfully updated the scope of related list entry record to global');
        } else {
            gs.info('Fix Related list Scope of App service: Updation of scope of related list entry record to global failed');
        }
    } else {
        gs.info('Fix Related list Scope of App service: No updation of scope is required');
    }
}
